css:
.donaldosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a2e22;
    background: linear-gradient(165deg, #fbf4e8 0%, #f3e6cf 55%, #ecdcc0 100%);
    border-radius: 18px;
}

.donaldosim-container * {
    box-sizing: border-box;
}

.donaldosim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #7a3b1d 0%, #a8501f 55%, #c46a2a 100%);
    color: #fff6e9;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #6a3217;
    box-shadow: 0 12px 30px rgba(122, 59, 29, 0.35);
}

.donaldosim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff8ee;
}

.donaldosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd9a8;
    background: rgba(255, 217, 168, 0.16);
    border: 1px solid rgba(255, 217, 168, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.donaldosim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ffeed8;
}

.donaldosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6d5840;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.donaldosim-period-counter #currentDay,
.donaldosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #a8501f;
}

.donaldosim-round-name {
    background: rgba(168, 80, 31, 0.14);
    color: #a8501f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.donaldosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a12;
    background: rgba(214, 158, 46, 0.18);
    border: 1px solid rgba(214, 158, 46, 0.45);
    padding: 4px 12px;
    border-radius: 999px;
}

.donaldosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.donaldosim-status-card {
    background: linear-gradient(160deg, #ffffff 0%, #fdf6ea 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6d3b3;
    box-shadow: 0 6px 16px rgba(122, 59, 29, 0.12);
    border-top: 4px solid #c46a2a;
}

.donaldosim-card-runway { border-top-color: #2f8f5b; }
.donaldosim-card-depth { border-top-color: #b07a1e; }
.donaldosim-card-control { border-top-color: #7a3b1d; }
.donaldosim-card-family { border-top-color: #c0533f; }

.donaldosim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7257;
}

.donaldosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3a2e22;
    font-variant-numeric: tabular-nums;
}

.donaldosim-card-runway .donaldosim-value { color: #2f8f5b; }
.donaldosim-card-depth .donaldosim-value { color: #b07a1e; }
.donaldosim-card-control .donaldosim-value { color: #7a3b1d; }
.donaldosim-card-family .donaldosim-value { color: #c0533f; }

.donaldosim-sublabel {
    font-size: 0.76rem;
    color: #97826a;
    line-height: 1.35;
}

.donaldosim-runway-critical { border-top-color: #d33a2c; }
.donaldosim-runway-critical .donaldosim-value { color: #d33a2c; }
.donaldosim-runway-healthy { border-top-color: #2f8f5b; }
.donaldosim-runway-healthy .donaldosim-value { color: #2f8f5b; }

.donaldosim-control-low { border-top-color: #d33a2c; }
.donaldosim-control-low .donaldosim-value { color: #d33a2c; }

.donaldosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff8ec;
    border: 1px solid #e6d3b3;
    color: #5a4631;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.donaldosim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #a8501f;
}

.donaldosim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #ffffff 0%, #fdf4e4 100%);
    border-left: 5px solid #c46a2a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(122, 59, 29, 0.10);
}

.donaldosim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.donaldosim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #7a3b1d;
    margin-bottom: 6px;
}

.donaldosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3a2a;
}

.donaldosim-briefing-text strong { color: #a8501f; }
.donaldosim-briefing-text em { color: #2f8f5b; font-style: italic; }

.donaldosim-controls {
    background: linear-gradient(160deg, #ffffff 0%, #fdf6ea 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6d3b3;
    box-shadow: 0 6px 16px rgba(122, 59, 29, 0.10);
}

.donaldosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #7a3b1d;
    border-bottom: 2px solid #ecdcc0;
    padding-bottom: 8px;
}

.donaldosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a4631;
    margin: 14px 0 6px;
}

.donaldosim-container select,
.donaldosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c19a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #3a2e22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.donaldosim-container select:focus,
.donaldosim-container input[type="number"]:focus {
    outline: none;
    border-color: #c46a2a;
    box-shadow: 0 0 0 3px rgba(196, 106, 42, 0.20);
}

.donaldosim-container select option {
    background-color: #fffdf8;
    color: #3a2e22;
}

.donaldosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c46a2a;
}

.donaldosim-range-readout,
.donaldosim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6d5840;
    margin-top: 4px;
}

.donaldosim-range-readout span:last-child,
.donaldosim-alloc-readout span:nth-child(2) {
    color: #a8501f;
    font-weight: 800;
}

.donaldosim-hint {
    font-size: 0.8rem;
    color: #97826a;
    margin-top: 4px;
    line-height: 1.4;
    font-style: italic;
}

.donaldosim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.donaldosim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fff8ec;
    border: 1px solid #e6d3b3;
    border-radius: 9px;
    padding: 8px 12px;
}

.donaldosim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #5a4631;
}

.donaldosim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.donaldosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.donaldosim-container .btn-primary {
    background: linear-gradient(135deg, #a8501f 0%, #c46a2a 100%);
    border: none;
    color: #fff6e9;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(168, 80, 31, 0.35);
}

.donaldosim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.donaldosim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c19a;
    color: #8a7257;
    background: transparent;
}

.donaldosim-coach {
    background: linear-gradient(160deg, #2f5235 0%, #3d6b44 100%);
    color: #eaf6ec;
    border: 1px solid #244029;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(47, 82, 53, 0.28);
}

.donaldosim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #aee3b6;
    margin-bottom: 8px;
}

.donaldosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.donaldosim-coach-body strong { color: #ffd9a8; }
.donaldosim-coach-body em { color: #aee3b6; font-style: italic; }

.donaldosim-history,
.donaldosim-chart {
    background: linear-gradient(160deg, #ffffff 0%, #fdf6ea 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6d3b3;
    box-shadow: 0 6px 16px rgba(122, 59, 29, 0.10);
}

.donaldosim-history h3,
.donaldosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #7a3b1d;
}

.donaldosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3a2a;
}

.donaldosim-container table#usfHistoryTable th {
    background: #f3e6cf;
    color: #7a3b1d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0cba4;
}

.donaldosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecdcc0;
    color: #4a3a2a;
}

.donaldosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf6ea;
}

.donaldosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .donaldosim-container {
        padding: 14px;
    }
    .donaldosim-header h1 {
        font-size: 1.7rem;
    }
    .donaldosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .donaldosim-value {
        font-size: 2rem;
    }
    .donaldosim-clock {
        margin-left: 0;
    }
    .donaldosim-period-counter {
        font-size: 0.88rem;
    }
    .donaldosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .donaldosim-alloc-row {
        flex-wrap: wrap;
    }
    .donaldosim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .donaldosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (donaldosim) ---- */
.donaldosim-completion { padding: 8px 4px 4px; }
.donaldosim-cm-head { text-align: center; margin-bottom: 16px; }
.donaldosim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #8a5a2f; }
.donaldosim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #b89275; }
.donaldosim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #332619; }
.donaldosim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.donaldosim-cm-yes { background: rgba(47,143,91,0.16); color: #2f8f5b; border: 1px solid rgba(47,143,91,0.5); }
.donaldosim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.donaldosim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.donaldosim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(138,90,47,0.08); border: 1px solid rgba(138,90,47,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.donaldosim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #8a5a2f; }
.donaldosim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.donaldosim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #332619; }
.donaldosim-cm-insights { margin: 0; padding-left: 20px; }
.donaldosim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

