(function() {
    'use strict';

    class DonAldoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Scaling the Family Firm`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Alimentos Don Aldo S.A.) — all AR$ millions.
            this.REVENUE = 9600;             // AR$9,600M (≈ US$8.0M @ ~1,200 ARS/USD)
            this.FCF = 700;                  // AR$700M free cash flow / year
            this.CONTRACT_REV = 4200;        // AR$4,200M incremental annual revenue
            this.CAPEX = 1500;               // AR$1,500M freezing tunnel + cold store
            this.WORKING_CAPITAL = 860;      // ~AR$860M trapped on 75-day terms
            this.TOTAL_NEED = 2360;          // CapEx + working capital
            this.GM_COST = 90;               // AR$90M/year external GM/COO
            this.PE_OFFER = 1200;            // AR$1,200M for 30% (post-money AR$4,000M)
            this.EBITDA = 1056;              // ~11% of AR$9,600M
            this.FX = 1200;                  // ARS per USD reference

            // Concept truths (the integrated transition).
            this.TRUE_GAP = `capability`;
            this.TRUE_RUNWAY = `tight`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    runway: 12,              // months of cash before the firm runs dry
                    depth: 18,               // management depth / delegated decision rights
                    control: 100,            // owner control retained (family ownership + governance)
                    family: 55,              // family alignment & three-circle clarity
                    layerCost: 0,            // AR$M annual cost of the new mgmt & governance layer
                    overLeveraged: false,
                    expensiveSpectator: false,
                    gaveAwayControl: false,
                    deferredSuccession: false,
                    lostToRival: false,
                    runwayHistory: [12],
                    depthHistory: [18],
                    controlHistory: [100],
                    familyHistory: [55],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately a MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    gap: `capital`,
                    runwayEst: `loose`,
                    separate: 40,
                    leader: `aldo`,
                    delegate: 20,
                    signatory: `single`,
                    keyaccount: `none`,
                    recommend: `full`,
                    debt: 60,
                    supplier: 10,
                    retained: 30,
                    equity: 0,
                    terms: `na`,
                    timing: `defer`,
                    governance: `none`,
                    succession: `pick`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gp = document.getElementById(`gapInput`);
                const re = document.getElementById(`runwayEstInput`);
                const sp = document.getElementById(`separateInput`);
                if (gp) decisions.gap = gp.value;
                if (re) decisions.runwayEst = re.value;
                if (sp) decisions.separate = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.separate) || decisions.separate < 0 || decisions.separate > 100) {
                    warn(`warn_separate_range`); return false;
                }
            } else if (round === 2) {
                const ld = document.getElementById(`leaderInput`);
                const dg = document.getElementById(`delegateInput`);
                const sg = document.getElementById(`signatoryInput`);
                const ka = document.getElementById(`keyaccountInput`);
                if (ld) decisions.leader = ld.value;
                if (dg) decisions.delegate = parseInt(dg.value, 10);
                if (sg) decisions.signatory = sg.value;
                if (ka) decisions.keyaccount = ka.value;
                if (!Number.isFinite(decisions.delegate) || decisions.delegate < 0 || decisions.delegate > 100) {
                    warn(`warn_delegate_range`); return false;
                }
            } else if (round === 3) {
                const rc = document.getElementById(`recommendInput`);
                const db = document.getElementById(`debtInput`);
                const su = document.getElementById(`supplierInput`);
                const rt = document.getElementById(`retainedInput`);
                const eq = document.getElementById(`equityInput`);
                const tm = document.getElementById(`termsInput`);
                if (rc) decisions.recommend = rc.value;
                if (db) decisions.debt = parseFloat(db.value);
                if (su) decisions.supplier = parseFloat(su.value);
                if (rt) decisions.retained = parseFloat(rt.value);
                if (eq) decisions.equity = parseFloat(eq.value);
                if (tm) decisions.terms = tm.value;
                const parts = [decisions.debt, decisions.supplier, decisions.retained, decisions.equity];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_fin_negative`); return false;
                }
                // The financing mix must total 100% only when the team is actually funding
                // a deal (go or scale-down). On decline there is nothing to finance.
                if (decisions.recommend !== `decline`) {
                    const total = Math.round(decisions.debt + decisions.supplier + decisions.retained + decisions.equity);
                    if (total !== 100) {
                        warn(`warn_fin_total`); return false;
                    }
                }
            } else if (round === 4) {
                const tg = document.getElementById(`timingInput`);
                const gv = document.getElementById(`governanceInput`);
                const sc = document.getElementById(`successionInput`);
                const cv = document.getElementById(`convictionInput`);
                if (tg) decisions.timing = tg.value;
                if (gv) decisions.governance = gv.value;
                if (sc) decisions.succession = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let runwayDelta = 0, depthDelta = 0, controlDelta = 0, familyDelta = 0, costDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the scaling gap — capability is the FIRST binding constraint.
                switch (d.gap) {
                    case `capability`: depthDelta += 8; familyDelta += 4; coachKey = `coach_r1_capability`; break;
                    case `capital`: depthDelta -= 2; coachKey = `coach_r1_capital`; break;
                    case `demand`: depthDelta -= 4; familyDelta -= 2; coachKey = `coach_r1_demand`; break;
                    case `margin`: depthDelta -= 4; coachKey = `coach_r1_margin`; break;
                }

                // Estimate the cash runway under the 75-day working-capital draw.
                switch (d.runwayEst) {
                    case `tight`: depthDelta += 4; familyDelta += 4; if (d.gap === `capability`) coachKey = `coach_r1_sharp`; break;
                    case `loose`: runwayDelta -= 1; break;
                    case `never`: runwayDelta -= 2; familyDelta -= 2; coachKey = `coach_r1_runwaynaive`; break;
                }

                // Clarity in separating capability vs capital.
                if (d.separate >= 60) { depthDelta += 5; familyDelta += 4; }
                else if (d.separate <= 25) { depthDelta -= 3; familyDelta -= 2; coachKey = `coach_r1_blurred`; }

                summaryKey = (d.gap === `capability` && d.runwayEst === `tight`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Professionalize management — delegation, not headcount (Common Errors 1 & 3).
                const delg = d.delegate / 100;

                switch (d.leader) {
                    case `gm_authority`:
                        depthDelta += 16 * delg + 4; costDelta += this.GM_COST; familyDelta += 2; coachKey = `coach_r2_gmauthority`; break;
                    case `gm_titleonly`:
                        // An expensive spectator: pay for the GM, get little depth unless authority moves.
                        depthDelta += 6 * delg; costDelta += this.GM_COST; controlDelta -= 2;
                        if (delg <= 0.25) { ds.expensiveSpectator = true; coachKey = `coach_r2_spectator`; } else { coachKey = `coach_r2_gmpartial`; }
                        break;
                    case `heir`:
                        depthDelta += 5 * delg; familyDelta -= 6; coachKey = `coach_r2_heir`; break;
                    case `aldo`:
                        depthDelta -= 6; familyDelta -= 2; coachKey = `coach_r2_aldo`; break;
                }

                // Banking signatory & PO threshold — the real single-point-of-failure.
                switch (d.signatory) {
                    case `dual`: depthDelta += 10; runwayDelta += 1; familyDelta += 3; break;
                    case `raise`: depthDelta += 3; break;
                    case `single`: depthDelta -= 6; familyDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_signatory`; break;
                }

                // Key-account / EDI team the retailer requires.
                switch (d.keyaccount) {
                    case `full`: depthDelta += 6; costDelta += 60; runwayDelta -= 0.5; break;
                    case `partial`: depthDelta += 2; costDelta += 20; break;
                    case `none`: depthDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_nokeyaccount` : coachKey; break;
                }

                // A high-headcount, low-delegation combination IS the founder's trap.
                if ((d.leader === `gm_titleonly` || d.leader === `gm_authority`) && d.delegate <= 20 && d.signatory === `single`) {
                    ds.expensiveSpectator = true;
                    depthDelta -= 4; coachKey = `coach_r2_trap`;
                }

                summaryKey = (d.leader === `gm_authority` && d.delegate >= 50 && d.signatory === `dual`) ? `sum_r2_good` :
                             (ds.expensiveSpectator ? `sum_r2_spectator` : `sum_r2_weak`);
            } else if (round === 3) {
                // Finance the growth without losing control (Common Errors 2, 5, 6).
                const debt = d.debt / 100, supplier = d.supplier / 100, retained = d.retained / 100, equity = d.equity / 100;

                if (d.recommend === `decline`) {
                    // Walking away protects the balance sheet but hands the listing to Córdoba.
                    ds.lostToRival = true;
                    runwayDelta += 2; controlDelta += 2; depthDelta -= 4; familyDelta -= 2;
                    coachKey = `coach_r3_decline`;
                    summaryKey = `sum_r3_decline`;
                } else {
                    const scale = (d.recommend === `scaledown`) ? 0.4 : 1.0;
                    if (d.recommend === `scaledown`) ds.lostToRival = true;

                    // Debt: keeps control, but 75-day terms delay the cash that services it.
                    // Heavy debt drives leverage toward ~3.1x EBITDA and starves the runway.
                    const newDebt = this.TOTAL_NEED * scale * debt;
                    const leverage = 0.8 + (newDebt / this.EBITDA);
                    runwayDelta -= debt * 6 * scale;
                    if (leverage >= 3.0) { ds.overLeveraged = true; runwayDelta -= 2; coachKey = `coach_r3_alldebt`; }

                    // Supplier / retailer finance directly eases the 75-day cash trap.
                    runwayDelta += supplier * 4 * scale;

                    // Retained earnings: no dilution, no leverage, but finite — over-reliance starves cash.
                    runwayDelta -= retained * 3 * scale;
                    if (retained >= 0.6) runwayDelta -= 1.5;

                    // PE equity: solves cash and runway, but dilutes control ~30% on a full draw.
                    runwayDelta += equity * 5 * scale;
                    controlDelta -= equity * 30 * scale;

                    // The contract itself, if funded with real depth, eventually extends the runway.
                    if (ds.depth >= 50) runwayDelta += 1.5 * scale;

                    // PE term negotiation shapes control as much as the headline percentage.
                    if (equity > 0) {
                        if (d.terms === `negotiate`) { controlDelta += equity * 12 * scale; familyDelta += 3; coachKey = `coach_r3_negotiated`; }
                        else if (d.terms === `headline`) { ds.gaveAwayControl = true; controlDelta -= 10; familyDelta -= 2; coachKey = `coach_r3_headline`; }
                    }

                    if (d.recommend === `scaledown` && coachKey === `coach_default`) coachKey = `coach_r3_scaledown`;
                    else if (coachKey === `coach_default`) coachKey = `coach_r3_balanced`;

                    const fundedRunway = (ds.runway + runwayDelta) > 6;
                    const keptControl = (ds.control + controlDelta) >= 60;
                    summaryKey = (d.recommend === `full` && fundedRunway && keptControl && !ds.overLeveraged) ? `sum_r3_good` :
                                 (ds.overLeveraged ? `sum_r3_leveraged` :
                                 (d.recommend === `scaledown` ? `sum_r3_scaledown` : `sum_r3_weak`));
                }
            } else if (round === 4) {
                // Open the succession question — a continuity discipline (Common Error 4).
                switch (d.timing) {
                    case `proactive`: familyDelta += 14; depthDelta += 4; runwayDelta += 1; coachKey = `coach_r4_proactive`; break;
                    case `signal`: familyDelta += 2; coachKey = `coach_r4_signal`; break;
                    case `defer`: ds.deferredSuccession = true; familyDelta -= 12; depthDelta -= 4; coachKey = `coach_r4_defer`; break;
                }

                switch (d.governance) {
                    case `full`: familyDelta += 12; controlDelta += 6; costDelta += 40; depthDelta += 5; break;
                    case `protocol`: familyDelta += 6; controlDelta += 3; costDelta += 15; break;
                    case `none`: familyDelta -= 6; controlDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r4_nogovernance`; break;
                }

                switch (d.succession) {
                    case `path`: familyDelta += 10; depthDelta += 4; if (d.timing === `proactive`) coachKey = `coach_r4_continuity`; break;
                    case `pick`: familyDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_pick` : coachKey; break;
                    case `avoid`: familyDelta -= 8; depthDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_avoid` : coachKey; break;
                }

                if (d.conviction >= 60) { familyDelta += 5; depthDelta += 2; }
                else if (d.conviction <= 25) { familyDelta -= 5; coachKey = `coach_r4_lowconviction`; }

                summaryKey = (d.timing === `proactive` && d.governance === `full` && d.succession === `path`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cost accounting: the annualized cost of the new management & governance layer.
            ds.layerCost = Math.max(0, Math.round(ds.layerCost + costDelta));

            // The new layer's cost draws on free cash flow and so trims the runway a little.
            runwayDelta -= costDelta / 220;

            // Apply deltas, clamped. Runway floors at 0 (the firm runs dry).
            ds.runway = Math.max(0, Math.round((ds.runway + runwayDelta) * 10) / 10);
            ds.depth = Math.max(0, Math.min(100, Math.round(ds.depth + depthDelta)));
            ds.control = Math.max(0, Math.min(100, Math.round(ds.control + controlDelta)));
            ds.family = Math.max(0, Math.min(100, Math.round(ds.family + familyDelta)));

            ds.runwayHistory.push(ds.runway);
            ds.depthHistory.push(ds.depth);
            ds.controlHistory.push(ds.control);
            ds.familyHistory.push(ds.family);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                runway: ds.runway,
                runwayDelta: Math.round(runwayDelta * 10) / 10,
                depth: ds.depth,
                depthDelta: Math.round(depthDelta),
                control: ds.control,
                controlDelta: Math.round(controlDelta),
                family: ds.family,
                familyDelta: Math.round(familyDelta),
                layerCost: ds.layerCost,
                overLeveraged: ds.overLeveraged,
                expensiveSpectator: ds.expensiveSpectator,
                gaveAwayControl: ds.gaveAwayControl,
                deferredSuccession: ds.deferredSuccession,
                lostToRival: ds.lostToRival,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMonths(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            return lang === `es` ? `${String(n).replace(`.`, `,`)} mes` : `${n} mo`;
        }

        _fmtMoney(v) {
            // ARS millions, kept visually distinct from the US$ reference. English "AR$700M";
            // Spanish "AR$700M" with comma decimals — never a bare $.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v));
            if (lang === `es`) {
                return `AR$${String(n).replace(/\B(?=(\d{3})+(?!\d))/g, `.`)}M`;
            }
            return `AR$${String(n).replace(/\B(?=(\d{3})+(?!\d))/g, `,`)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const card = document.querySelector(`.donaldosim-card-runway`);
                if (card) {
                    card.classList.toggle(`donaldosim-runway-critical`, Number(v) <= 4);
                    card.classList.toggle(`donaldosim-runway-healthy`, Number(v) >= 12);
                }
                return self._fmtMonths(Number(v));
            });
            uiManager.bind(`depthDisplay`, `domainState.depth`, (v) => Math.round(Number(v)));
            uiManager.bind(`controlDisplay`, `domainState.control`, (v) => {
                const card = document.querySelector(`.donaldosim-card-control`);
                if (card) card.classList.toggle(`donaldosim-control-low`, Number(v) < 60);
                return Math.round(Number(v));
            });
            uiManager.bind(`familyDisplay`, `domainState.family`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.layerCost`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.FCF) + ` ` + window.mySimulation.t(`fcf_tag`);
            });

            // Round 1 — capability/capital separation slider readout.
            const sp = document.getElementById(`separateInput`);
            const spReadout = document.getElementById(`separateReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }

            // Round 2 — delegation slider readout.
            const dg = document.getElementById(`delegateInput`);
            const dgReadout = document.getElementById(`delegateReadout`);
            if (dg && dgReadout) {
                dgReadout.textContent = dg.value;
                dg.addEventListener(`input`, function() { dgReadout.textContent = dg.value; });
            }

            // Round 3 — financing mix live total (must hit 100%).
            const allocIds = [`debtInput`, `supplierInput`, `retainedInput`, `equityInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.donaldosim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#d33a2c` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

