        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.depthHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                donaldoChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.depthHistory },
                        { data: ds.controlHistory },
                        { data: ds.familyHistory },
                        { data: ds.runwayHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const runway = Math.round(ds.runway * 10) / 10;
            const depth = Math.round(ds.depth);
            const control = Math.round(ds.control);
            const family = Math.round(ds.family);
            const runwayScore = Math.max(0, Math.min(100, runway * 6));
            return Math.max(0, Math.min(100, Math.round(runwayScore * 0.28 + depth * 0.26 + control * 0.22 + family * 0.24)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const runway = Math.round(ds.runway * 10) / 10;
            const depth = Math.round(ds.depth);
            const control = Math.round(ds.control);
            const family = Math.round(ds.family);

            // Composite: a balanced scale-up needs all four — survival (runway),
            // a management spine (depth), retained control, and family alignment.
            const composite = this._composite(ds);

            const solvent = runway > 4;
            const professionalized = depth >= 60;
            const controlled = control >= 60;
            const aligned = family >= 60;
            const fractured = ds.deferredSuccession && family < 45;

            let performance = window.mySimulation.t(`grade_stalled`);
            if (solvent && professionalized && controlled && aligned && composite >= 75) performance = window.mySimulation.t(`grade_built`);
            else if (professionalized && solvent && (controlled || aligned)) performance = window.mySimulation.t(`grade_spine`);
            else if (!solvent) performance = window.mySimulation.t(`grade_dry`);
            else if (fractured || ds.expensiveSpectator) performance = window.mySimulation.t(`grade_trap`);
            else if (ds.gaveAwayControl) performance = window.mySimulation.t(`grade_diluted`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_partial`);

            const insights = [];
            if (solvent && professionalized && controlled && aligned) insights.push(window.mySimulation.t(`insight_built`));
            else if (!solvent) insights.push(window.mySimulation.t(`insight_dry`));
            else if (ds.expensiveSpectator) insights.push(window.mySimulation.t(`insight_spectator`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (ds.overLeveraged) insights.push(window.mySimulation.t(`insight_leverage`));
            if (ds.gaveAwayControl) insights.push(window.mySimulation.t(`insight_dilution`));
            if (ds.deferredSuccession) insights.push(window.mySimulation.t(`insight_succession`));
            if (ds.lostToRival) insights.push(window.mySimulation.t(`insight_rival`));
            if (professionalized && controlled && aligned) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                runway: runway,
                depth: depth,
                control: control,
                family: family,
                solvent: solvent,
                professionalized: professionalized,
                controlled: controlled,
                aligned: aligned,
                met: (solvent && professionalized && controlled && aligned && composite >= 75),
                notSolvent: !solvent,
                gaveAwayControl: !!ds.gaveAwayControl,
                founderTrap: !!ds.expensiveSpectator,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="donaldosim-cm-badge donaldosim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="donaldosim-cm-badge donaldosim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.notSolvent) failBadge += ` <span class="donaldosim-cm-badge donaldosim-cm-no">` + T(`cm_dry`) + `</span>`;
            if (s.founderTrap) failBadge += ` <span class="donaldosim-cm-badge donaldosim-cm-no">` + T(`cm_trap`) + `</span>`;
            if (s.gaveAwayControl) failBadge += ` <span class="donaldosim-cm-badge donaldosim-cm-no">` + T(`cm_diluted`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="donaldosim-cm-metric"><span class="donaldosim-cm-mv">` + Math.round(s.runway || 0) + `</span><span class="donaldosim-cm-ml">` + T(`cm_m_runway`) + `</span></div>`
                + `<div class="donaldosim-cm-metric"><span class="donaldosim-cm-mv">` + Math.round(s.depth || 0) + `</span><span class="donaldosim-cm-ml">` + T(`cm_m_depth`) + `</span></div>`
                + `<div class="donaldosim-cm-metric"><span class="donaldosim-cm-mv">` + Math.round(s.control || 0) + `</span><span class="donaldosim-cm-ml">` + T(`cm_m_control`) + `</span></div>`
                + `<div class="donaldosim-cm-metric"><span class="donaldosim-cm-mv">` + Math.round(s.family || 0) + `</span><span class="donaldosim-cm-ml">` + T(`cm_m_family`) + `</span></div>`;
            return ``
                + `<div class="donaldosim-completion">`
                +   `<div class="donaldosim-cm-head">`
                +     `<div class="donaldosim-cm-score">` + score + `<span class="donaldosim-cm-score-max">/100</span></div>`
                +     `<div class="donaldosim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="donaldosim-cm-metrics">` + metrics + `</div>`
                +   `<div class="donaldosim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="donaldosim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.runway <= 4) return window.mySimulation.t(`hint_runway`);
            if (ds.expensiveSpectator) return window.mySimulation.t(`hint_spectator`);
            if (ds.overLeveraged) return window.mySimulation.t(`hint_leverage`);
            if (ds.gaveAwayControl) return window.mySimulation.t(`hint_dilution`);
            if (state.currentPeriod >= 3 && ds.depth < 45) return window.mySimulation.t(`hint_depth`);
            if (state.currentPeriod >= 4 && ds.family < 45) return window.mySimulation.t(`hint_family`);
            if (ds.depth >= 60 && ds.control >= 60 && ds.family >= 60 && ds.runway > 6) return window.mySimulation.t(`hint_strong`);
            return null;
        }

